import axios from 'axios'

const BACKEND_URL = 'http://localhost:3000'

// Créer une instance axios avec la configuration par défaut
const api = axios.create({
  baseURL: BACKEND_URL,
  withCredentials: true // Important pour les cookies de session
});

// Ajouter l'intercepteur pour le token
api.interceptors.request.use(config => {
  const token = localStorage.getItem('token');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

export default {
  namespaced: true,

  state: {
    balance: 0,
    cryptoHoldings: {},
    transactions: [],
    pendingDeposit: null,
    pendingWithdrawal: null
  },

  mutations: {
    SET_BALANCE(state, balance) {
      state.balance = balance
    },
    SET_CRYPTO_HOLDINGS(state, holdings) {
      state.cryptoHoldings = holdings
    },
    SET_TRANSACTIONS(state, transactions) {
      state.transactions = transactions
    },
    SET_PENDING_DEPOSIT(state, deposit) {
      state.pendingDeposit = deposit
    },
    ADD_TRANSACTION(state, transaction) {
      state.transactions.unshift(transaction)
    },
    SET_PENDING_WITHDRAWAL(state, withdrawal) {
      state.pendingWithdrawal = withdrawal
    }
  },

  actions: {
    async fetchWalletData({ commit }) {
      try {
        const [balanceRes, holdingsRes, transactionsRes] = await Promise.all([
          api.get('/api/wallet/balance'),
          api.get('/api/wallet/holdings'),
          api.get('/api/wallet/transactions')
        ])

        commit('SET_BALANCE', balanceRes.data.balance)
        commit('SET_CRYPTO_HOLDINGS', holdingsRes.data)
        commit('SET_TRANSACTIONS', transactionsRes.data)
      } catch (error) {
        console.error('Erreur fetchWalletData:', error)
        throw error.response?.data || error.message
      }
    },

    async requestDeposit({ commit }, { amount, paymentMethod }) {
      try {
        const response = await api.post('/api/wallet/deposit/request', {
          amount,
          paymentMethod
        })
        commit('SET_PENDING_DEPOSIT', response.data)
        return response.data
      } catch (error) {
        throw error.response?.data || error.message
      }
    },

    async confirmDeposit({ commit, dispatch }, { depositId, verificationCode }) {
      try {
        await api.post('/api/wallet/deposit/confirm', {
          depositId,
          verificationCode
        })
        commit('SET_PENDING_DEPOSIT', null)
        await dispatch('fetchWalletData')
      } catch (error) {
        throw error.response?.data || error.message
      }
    },

    async requestWithdrawal({ dispatch }, { amount, bankDetails }) {
      try {
        await api.post('/api/wallet/withdraw', {
          amount,
          bankDetails
        })
        await dispatch('fetchWalletData')
      } catch (error) {
        throw error.response?.data || error.message
      }
    },

    async executeTrade({ dispatch }, { type, crypto, amount }) {
      try {
        const response = await api.post('/api/trade', {
          type, // 'buy' ou 'sell'
          crypto,
          amount
        })
        await dispatch('fetchWalletData')
        return response.data
      } catch (error) {
        throw error.response?.data || error.message
      }
    },

    async deposit({ dispatch }, amount) {
      try {
        const response = await api.post('/api/wallet/deposit', { amount });
        if (response.data.status === 'success') {
          await dispatch('fetchWalletData');
          return { success: true, message: 'Dépôt effectué avec succès' };
        }
      } catch (error) {
        console.error('Erreur deposit:', error);
        throw error.response?.data || { message: 'Erreur lors du dépôt' };
      }
    },

    async initiateWithdrawal({ commit }, amount) {
      try {
        const response = await api.post('/api/wallet/withdraw', { amount });
        if (response.data.status === 'success') {
          commit('SET_PENDING_WITHDRAWAL', {
            transactionId: response.data.transactionId,
            amount
          });
          return response.data;
        }
      } catch (error) {
        console.error('Erreur initiateWithdrawal:', error);
        throw error.response?.data || { message: 'Erreur lors du retrait' };
      }
    },

    async confirmWithdrawal({ commit, dispatch }, { transactionId, code }) {
      try {
        const response = await api.post('/api/wallet/withdraw/verify', {
          transactionId,
          code
        });
        if (response.data.status === 'success') {
          commit('SET_PENDING_WITHDRAWAL', null);
          await dispatch('fetchWalletData');
          return { success: true, message: 'Retrait effectué avec succès' };
        }
      } catch (error) {
        console.error('Erreur confirmWithdrawal:', error);
        throw error.response?.data || { message: 'Erreur lors de la confirmation' };
      }
    }
  },

  getters: {
    getBalance: state => state.balance,
    getCryptoHoldings: state => state.cryptoHoldings,
    getTransactions: state => state.transactions,
    getPendingDeposit: state => state.pendingDeposit,
    getPendingWithdrawal: state => state.pendingWithdrawal,
    getTotalPortfolioValue: (state, _, rootState) => {
      const prices = rootState.crypto.prices
      let total = state.balance

      Object.entries(state.cryptoHoldings).forEach(([crypto, amount]) => {
        if (prices[crypto]) {
          total += amount * prices[crypto]
        }
      })

      return total
    }
  }
}
